fn parse_age(s: Str) -> Option[Int] {
  // simplified: accept "15" as valid
  if s == "15" { return Some(15); }
  return None;
}

fn categorize(age: Int) -> Option[Str] {
  if age < 13 { return Some("Child"); }
  if age <= 19 { return Some("Teen"); }
  if age <= 120 { return Some("Adult"); }
  return None;
}

fn main() -> Int {
  let result = parse_age("15").and_then(|a| categorize(a));
  return result.unwrap_or("").len();
}
